static long mono_ms(void)
{
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (long)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

/* Wall clock via software CLOCK_REALTIME (no RTC on this board, so it starts at
 * epoch on boot and is set by the user; LOCALTIME is off so we derive HH:MM from
 * epoch seconds directly and treat that as local time). */
static int wall_min(void)   /* minute-of-day 0..1439 */
{
  struct timespec ts;
  clock_gettime(CLOCK_REALTIME, &ts);
  return (int)((ts.tv_sec % 86400) / 60);
}
static long wall_day(void)  /* day number since epoch (for per-day resets) */
{
  struct timespec ts;
  clock_gettime(CLOCK_REALTIME, &ts);
  return (long)(ts.tv_sec / 86400);
}
static void wall_set_min(int minofday)  /* set clock to (current day) at HH:MM */
{
  struct timespec ts;
  clock_gettime(CLOCK_REALTIME, &ts);
  ts.tv_sec = (ts.tv_sec / 86400) * 86400 + (long)minofday * 60;
  ts.tv_nsec = 0;
  clock_settime(CLOCK_REALTIME, &ts);
}
static void wall_advance(int mins)      /* fast-forward (demo control) */
{
  struct timespec ts;
  clock_gettime(CLOCK_REALTIME, &ts);
  ts.tv_sec += (long)mins * 60;
  clock_settime(CLOCK_REALTIME, &ts);
}

